fn tri(n: usize, m: usize, k: i32) -> Vec<Vec<f64>> {
    let mut matrix = vec![vec![0.0; m]; n]; // Create an n-by-m matrix initialized with 0.0

    for i in 0..n {
        for j in 0..m {
            if j <= (i as i32 + k) {
                matrix[i][j] = 1.0; // Set the value to 1.0 if the condition is met
            }
        }
    }

    matrix // Return the constructed matrix
}

fn main() {
    // Example usage
    let n = 5;
    let m = 5;
    let k = 1;
    let result = tri(n, m, k);
    
    for row in result {
        println!("{:?}", row);
    }
}